command:
// ==========================================
// ⚙️ LUNAS WIRKUNG: FUNKENFELL (V13 Ready - Ehrenschulden Layout)
// ==========================================

(async () => {
    // ============================================================
    // 0. Framework laden & Wirkungsende-Hook registrieren
    // ============================================================
    const fwMacro = await fromUuid("Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn");
    if (fwMacro) {
        await fwMacro.execute();
    }

    if (typeof DSK === "undefined") {
        ui.notifications.error("Das DSK-Framework konnte nicht geladen werden!");
        return;
    }
    const DSK_FW = globalThis.DSK || DSK;

    const gabenName = "Funkenfell (Rondra)";
    const ahne = "rondra";

    // Hilfsfunktion: Finde alle Spieler-IDs, denen ein Akteur gehört
    const getOwners = (act) => {
        if (!act) return [];
        const ownership = act.ownership || act.permission || {};
        return Object.entries(ownership)
            .filter(([id, lvl]) => lvl === 3 && id !== "default")
            .map(([id]) => id);
    };

    if (DSK_FW.EffektEnde) {
        DSK_FW.EffektEnde.Register(
            "rondraFunkenfell", 
            gabenName, 
            "Die elektrische Ladung im Fell verzieht sich, und das Funkenfell erlischt wirkungslos."
        );
    }

    // ============================================================
    // 1. Initialisierung & Caster-Ermittlung
    // ============================================================
    const casterActor = (typeof testData !== "undefined" && testData?.actor) || 
                        (typeof testData !== "undefined" && testData?.speaker?.actor ? game.actors.get(testData.speaker.actor) : null) || 
                        (typeof testData !== "undefined" && testData?.speaker?.token ? canvas.tokens.get(testData.speaker.token)?.actor : null) || 
                        actor || 
                        canvas.tokens.controlled[0]?.actor || 
                        game.user.character;

    if (!casterActor) {
        ui.notifications.warn("Kein Akteur gefunden! Bitte wähle deinen Token aus.");
        return;
    }

    let qs = casterActor.getFlag("world", "letzteGabenQS") || 1;
    const alteMessageId = casterActor.getFlag("world", "letzteGabenMessageId");

    try {
        if (typeof testData !== "undefined" && testData) {
            const parsedQs = Number(testData?.result?.QL || testData?.qualityStep);
            if (!isNaN(parsedQs) && parsedQs > 0) qs = parsedQs;
        }
    } catch (e) {}

    const casterName = DSK_FW.ResolveTokenName(casterActor);

    // ============================================================
    // 2. Berechnungen (Dünn)
    // ============================================================
    const schaden = qs;
    const dauerRunden = qs * 2;

    const thinStyle = 'style="font-weight: 300; font-size: 0.9em; opacity: 0.8;"';
    const qsCalc = `<span ${thinStyle}>(${qs} QS)</span>`;

    const basisBeschreibung = `Das Fell des Rondrakindes lädt sich statisch auf.<br><br>• Der nächste Angreifer erleidet <b>${schaden} LeP Schaden</b> ${qsCalc}.<br>• Der Effekt endet nach der Schadensauslösung.`;
    const dauerText = `${dauerRunden} Kampfrunden`;

    let erfolgsZiele = [];
    let fehlschlagZiele = []; 

    // ============================================================
    // 3. EFFEKT ANLEGEN (Wirkender lädt sich selbst auf)
    // ============================================================
    try {
        let alterEffekt = casterActor.effects.find(e => e.name === gabenName);
        if (alterEffekt) await alterEffekt.delete();

        await DSK_FW.Effekt.Anwenden({
            name: gabenName,
            ahne: ahne,
            beschreibung: basisBeschreibung,
            gabeZiel: "", // Kein Filter nötig
            qs: qs,
            ziel: casterActor
        });

        const eff = casterActor.effects.find(e => e.name === gabenName);
        if (eff) {
            await eff.update({ duration: { rounds: dauerRunden } });
        }
        erfolgsZiele.push(casterName);
    } catch (e) {
        console.warn("Effekt konnte nicht angewendet werden:", e);
        fehlschlagZiele.push({ name: casterName, grund: "Fehler beim Anlegen" });
    }

    // --- FLAG-CLEANUP (Nur bei Erfolg) ---
    if (erfolgsZiele.length > 0) {
        await casterActor.unsetFlag("world", "letzteGabenQS");
        await casterActor.unsetFlag("world", "letzteGabenMessageId");
    }

    // ============================================================
    // 4. WHISPER-EMPFÄNGER & GEFÜSTERTE CHATKARTE ERSTELLEN
    // ============================================================
    let ownerIds = new Set(game.users.filter(u => u.isGM).map(u => u.id));
    getOwners(casterActor).forEach(id => ownerIds.add(id));
    const whisperEmpfaenger = Array.from(ownerIds).filter(id => game.users.get(id));

    let erfolgHtml = "";
    if (erfolgsZiele.length > 0) {
        erfolgHtml = `
            <p><span style="color:#18940F; font-weight:bold;">Erfolg</span></p>
            <p style="font-weight:bold; color:#000; margin: 4px 0 2px 0;">Funkenfell aktiv bei:</p>
            <ul class="dsklist" style="font-weight:normal; margin-top:4px;">
                ${erfolgsZiele.map(n => `<li>${n}</li>`).join("")}
            </ul>
        `;
    }

    let fehlschlagHtml = "";
    if (fehlschlagZiele.length > 0) {
        fehlschlagHtml = `
            <hr>
            <p><span style="color:#B30000; font-weight:bold;">Fehlschlag</span></p>
            <p style="font-weight:normal; color:#000; margin: 4px 0 2px 0;">(Systemfehler)</p>
            <ul class="dsklist" style="font-weight:normal; margin-top:0;">
                ${fehlschlagZiele.map(f => `<li>${f.name}</li>`).join("")}
            </ul>
        `;
    }

    const cardContent = `
        <div style="font-family: 'Signika', sans-serif;">
            ${DSK_FW.UI.Header(gabenName, DSK_FW.Symbol(ahne))}
            <div class="dskbox2" style="margin-top:10px;">
                <p><b>Gabenwirkung:</b></p>
                <p>Das Fell lädt sich statisch auf. Der nächste Angreifer erleidet <b>${schaden} LeP Schaden</b> ${qsCalc}.</p>
                <hr>
                ${erfolgHtml}
                ${fehlschlagHtml}
                <hr>
                <p style="text-align:center; font-weight:bold;">
                    Wirkungsdauer: ${dauerText}
                </p>
            </div>
        </div>
    `;

    let msg = alteMessageId ? game.messages.get(alteMessageId) : null;
    if (msg) {
        await msg.update({ content: cardContent });
    } else {
        const neueMsg = await ChatMessage.create({
            speaker: { alias: "System" },
            whisper: whisperEmpfaenger,
            content: cardContent
        });
        if (neueMsg && fehlschlagZiele.length > 0 && erfolgsZiele.length === 0) {
            await casterActor.setFlag("world", "letzteGabenMessageId", neueMsg.id);
        }
    }

    // ============================================================
    // 5. CHAT-HOOK FÜR SCHADENS-RÜCKSTOSS (WENN ANGEGRIFFEN)
    // ============================================================
    if (erfolgsZiele.length > 0) {
        const hookId = Hooks.on("createChatMessage", async (msgObj) => {
            const tmpDiv = document.createElement("div");
            tmpDiv.innerHTML = msgObj.content || "";
            const cleanText = (tmpDiv.textContent || tmpDiv.innerText || "").replace(/\s+/g, ' ').trim();

            const activeEffekt = casterActor.effects.find(e => e.name === gabenName);
            if (!activeEffekt) {
                // Sobald das Funkenfell weg ist (oder abgelaufen), löschen wir den Listener
                Hooks.off("createChatMessage", hookId);
                return;
            }

            // Prüft, ob jemand gegen das Rondrakind gewonnen hat
            if (cleanText.includes(casterName) && cleanText.includes("gewinnt gegen")) {
                const targetIdx = cleanText.indexOf(casterName);
                const winIdx = cleanText.indexOf("gewinnt gegen");

                if (targetIdx > winIdx) {
                    const match = cleanText.match(/(.*?)\s+gewinnt gegen/i);
                    const angreiferName = match ? match[1].trim() : "Der Angreifer";

                    const gmIds = ChatMessage.getWhisperRecipients("GM").map(u => u.id);
                    const allOwnerIds = Array.from(new Set([...gmIds, ...getOwners(casterActor)]));

                    const whisperHtml = `
                        <div style="font-family: 'Signika', sans-serif;">
                            <div class="dskbox1">
                                <p style="display:flex; align-items:center; gap:8px;">
                                    <img src="${DSK_FW.Symbol(ahne)}" style="width:28px;">
                                    <b>Funkenfell-Rückstoß</b>
                                </p>
                                <p style="text-align:center; font-weight:bold; margin-top:6px; color:#d9534f;">Gegenschaden gegen: ${angreiferName}</p>
                            </div>
                            <div class="dskbox2" style="margin-top:10px;">
                                <p style="font-size:0.95em; line-height:1.35;">
                                    <b>${angreiferName}</b> hat ${casterName} erfolgreich angegriffen und erleidet nun <b>${schaden} LeP Schaden</b> (${qs} QS) durch das Funkenfell!<br><br>
                                    <span style="font-size:0.85em; color:#555;">(Bitte markiere das Token von <b>${angreiferName}</b> und klicke auf den Button)</span>
                                </p>
                                <hr>
                                <button class="apply-funkenfell-btn"
                                    style="width:100%; cursor:pointer; background:linear-gradient(#76301b,#582617); color:#f8f6f5;
                                           border:1px solid #000; padding:5px 8px; border-radius:3px; font-weight:bold; margin-top: 5px; text-align:center;">
                                    ${schaden} LeP Schaden anwenden
                                </button>
                            </div>
                        </div>
                    `;

                    const whisperedMsg = await ChatMessage.create({
                        whisper: allOwnerIds,
                        content: whisperHtml,
                        speaker: ChatMessage.getSpeaker({ user: game.user })
                    });

                    // Button-Logik binden
                    Hooks.once("renderChatMessage", async (message, html) => {
                        if (message.id !== whisperedMsg.id) return;

                        html.find(".apply-funkenfell-btn").click(async () => {
                            const target = game.user.targets.first();
                            if (!target) {
                                return ui.notifications.warn("Bitte markiere zuerst das Token des Angreifers!");
                            }

                            const hpPath = target.actor.system.stats?.LeP ? "system.stats.LeP.value" : "system.hp.value";
                            const curHp = target.actor.system.stats?.LeP?.value ?? target.actor.system?.hp?.value ?? 0;
                            await target.actor.update({ [hpPath]: curHp - schaden });

                            ui.notifications.info(`${target.name} hat ${schaden} LeP Schaden durch Funkenfell erhalten!`);

                            // Nach Schadensauslösung wird das Funkenfell gelöscht!
                            await activeEffekt.delete(); 
                        });
                    });
                }
            }
        });
    }
})();
